const settleWindow = `-- name: SettleWindow :execrows
UPDATE billing.subscription_windows SET reserved = reserved - $1, used = used + $2
WHERE subscription_id = $3 AND seq = $4 AND $1 >= 0 AND $2 >= 0
`

type SettleWindowParams struct {
	Held           int64
	Charged        int64
	SubscriptionID uuid.UUID
	Seq            int32
}

// Settles a charge into the frozen window: the hold goes back and the charge is used. A charge above the hold is
// refused by the check, as the caller caps at the hold.
func (q *Queries) SettleWindow(ctx context.Context, db DBTX, arg SettleWindowParams) (int64, error) {
	result, err := db.Exec(ctx, settleWindow,
		arg.Held,
		arg.Charged,
		arg.SubscriptionID,
		arg.Seq,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

